 if(dayText!=""){
  if(!(dayText ~= "[0-9]{4}-[0-9]{2}-[0-9]{2}") || !isDate(dayText,"yyyy-MM-dd","en.US","UTC",true))return 5;
  date invoice=str2date(dayText,"yyyy-MM-dd","en.US","UTC",true);
  if(invoice<createDate(2026,1,1,"UTC"))return 2;
 }
